UPDATE app.region_setting s SET bg_temperature = 'warm', bg_types = ARRAY['textured', 'solid']::text[], motion = '[{"movement_types":[1,4],"directions":["ltr","bldtr"]},{"movement_types":[0,3],"directions":["rtl","trdbl"]},{"movement_types":[0,1],"directions":["btt"]}]'::jsonb, target_locations = ARRAY['E', 'SE', 'NE', 'N', 'S']::text[], rotation = 'ccw', clinical_status = 'draft', revision = s.revision + 1, updated_at = now() FROM app.brain_region b WHERE b.id = s.sublobe_id AND b.path = 'left.subcortical.basal_ganglia_direct';
